'use strict';

// MODULES //

var dfirstIndexEqual = require( '@stdlib/blas/ext/base/dfirst-index-equal' ).ndarray;


// MAIN //

/**
* Returns the index of the last element in a double-precision floating-point strided array equal to a corresponding element in another strided array using alternative indexing semantics.
*
* @param {PositiveInteger} N - number of indexed elements
* @param {Float64Array} x - first input array
* @param {integer} strideX - stride length for `x`
* @param {NonNegativeInteger} offsetX - starting index for `x`
* @param {Float64Array} y - second input array
* @param {integer} strideY - stride length for `y`
* @param {NonNegativeInteger} offsetY - starting index for `y`
* @returns {integer} index
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
*
* var x = new Float64Array( [ 1.0, 2.0, 3.0, 4.0 ] );
* var y = new Float64Array( [ 0.0, 0.0, 3.0, 0.0 ] );
*
* var idx = dlastIndexEqual( x.length, x, 1, 0, y, 1, 0 );
* // returns 2
*/
function dlastIndexEqual( N, x, strideX, offsetX, y, strideY, offsetY ) {
	var idx;
	var ox;
	var oy;
	var sx;
	var sy;

	if ( N <= 0 ) {
		return -1;
	}
	// Reverse the iteration order by flipping the strides and adjusting the offsets:
	ox = offsetX + ( ( N - 1 ) * strideX );
	oy = offsetY + ( ( N - 1 ) * strideY );
	sx = -strideX;
	sy = -strideY;

	// Find the index of the first matching element in the reversed "views":
	idx = dfirstIndexEqual( N, x, sx, ox, y, sy, oy );
	if ( idx < 0 ) {
		return idx;
	}
	// Convert the index from the reversed "views" to an index in the original "views":
	return N - 1 - idx;
}


// EXPORTS //

module.exports = dlastIndexEqual;
